package com.techconsulting.lending.domain;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.Instant;
@Entity @Table(name="import_batch") @Getter @Setter
public class ImportBatch { public enum ReportType { LOAN_REPORT,WALLET_TRANSACTION_REPORT,BANK_CREDIT_REPORT,EMAIL_RECEIPT_REPORT } public enum Status { UPLOADED,PROCESSING,COMPLETED,PARTIALLY_COMPLETED,FAILED }
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false) private Long userId; @Enumerated(EnumType.STRING) @Column(name="report_type") private ReportType reportType; @Column(name="original_file_name") private String originalFileName; @Column(name="file_checksum",columnDefinition="char(64)") private String fileChecksum; @Column(name="file_size") private long fileSize; @Enumerated(EnumType.STRING) private Status status; @Column(name="total_rows") private int totalRows; @Column(name="valid_rows") private int validRows; @Column(name="invalid_rows") private int invalidRows; @Column(name="inserted_rows") private int insertedRows; @Column(name="updated_rows") private int updatedRows; @Column(name="skipped_rows") private int skippedRows; @Column(name="failed_rows") private int failedRows; @Column(name="started_at") private Instant startedAt; @Column(name="completed_at") private Instant completedAt; @Column(name="error_message",columnDefinition="text") private String errorMessage; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; }
